# prompts.py - picture prompts for camp-century (all gpt-image-2.5-sunburst, 1K, quality LOW, 1 variation, NO references)
# (The hero was generated with the HELMET block "#5E6B3B / #434D29"; after measuring the hero the block became "#5B6737 / #434F29" for every later picture.)
# STYLE / CHARACTER / KEY / BG blocks word for word from memory/STYLE.md (the channel's locked look).
# The soldier pictures use a MAGENTA key (olive-green helmet). Objects are worded neutrally (no 'nuclear', 'missile', 'bomb'): earlier object sheets passed the content filter that way.
import json
CHAR = "Flat 2D cartoon: a simple white character with a big round head, a small soft body, noodle arms with simple four-finger hands and short legs with rounded feet, thick smooth black (#000000) outlines of even weight, about 2 % of the head width thick, flat white fill (#FEFDFD) with a very soft pale-grey shade (#EDEBEB) on the left side of the head and body, the round head is wider than the body and about 0.38 of the full body height, small solid black vertical oval eyes about one sixth of the head width tall, simple curved black eyebrows, no nose, no hair, no clothes, a pink tongue (#FC8D90) only when the mouth is open. Clean vector-like linework, flat colours, no texture, no text, no border."
HELMET = " This character is a soldier: exactly the same simple white character, wearing only a round dark olive-green army helmet with a short rim all around (flat #5B6737 with a darker #434F29 shade on the left side, as measured on the hero) sitting on top of the round head and covering only the top third of the head - nothing else added, no hair, no clothes, no straps, no badges."
OBJ = "Flat 2D cartoon in the same drawing style: bold clean thick smooth black outlines of even weight, flat colours with one simple soft shade, clean vector-like linework, simple shapes, no texture, no text, no letters, no numbers, no symbols, no logos, no border, no characters."
def KEY(c='green'):
    col = 'pure green (#00FF00)' if c == 'green' else 'pure magenta (#FF00FF)'
    return f"Isolated on a perfectly flat, uniform, solid {col} background that fills the whole picture edge to edge: no shadow, no ground, no floor line, no gradient, no vignette, no border, no other objects. The whole subject in frame with a clear margin on every side."
BG = "Flat 2D cartoon background in the same drawing style: big simple flat-colour shapes, thick smooth black outlines only on the main shapes, no texture, no text, no labels, no arrows, no characters, calm and simple so a character reads clearly on top of it."
ROW3 = "Three DIFFERENT poses of the same character side by side in one row, all three the same size, with wide empty gaps between them, every copy full body, no ground drawn, bold clean thick outlines. "
def tail(role=HELMET, key='magenta'): return " Whole bodies in frame with a margin. " + CHAR + role + " " + KEY(key)
SHOVEL = "a long straight wooden-handled shovel with a flat grey steel blade"
SCRAPER = "a long wooden pole with a wide flat grey steel scraper blade fixed across its far end, like a big floor scraper"
CASE = "a small brown suitcase with a handle (flat #8A5A34 with a darker #6A4226 shade)"

P = {
 'hero': ("2:3", "Full body, three-quarter view facing to the right, standing upright and proud, both arms relaxed at the sides, holding nothing, a small confident closed-mouth smile, eyebrows slightly raised. Whole body in frame with a margin. Bold clean thick outlines. " + CHAR + HELMET + " " + KEY('magenta')),
 'soldierA': ("3:2", ROW3 + f"LEFT copy: three-quarter view facing to the RIGHT, working hard: both hands holding {SHOVEL} diagonally in front of the body with a heap of white snow on the blade, leaning forward a little, a determined face with a small open mouth. MIDDLE copy: facing the viewer, presenting proudly: one arm stretched out to the RIGHT side of the image with the open palm facing up, as if saying 'ta-da', the other hand on the hip, eyes closed happily, a big proud open smile with the pink tongue showing. RIGHT copy: three-quarter view facing to the LEFT, acting innocent: holding a small round magnifying glass up beside the face in one hand, the other hand behind the back, eyes looking up and sideways, eyebrows raised, a sweet closed-mouth smile." + tail()),
 'soldierB': ("3:2", ROW3 + "LEFT copy: facing the viewer, secretive: the index finger of one hand pressed against the closed mouth in a 'shh' gesture, the other arm down, eyes looking sideways to the RIGHT, eyebrows lowered, a sly look. MIDDLE copy: facing the viewer, scared: looking straight up, eyebrows tilted up in the middle, eyes wide open, the mouth wide open in an 'O' with the pink tongue showing, both open hands raised beside the head. RIGHT copy: three-quarter view facing to the RIGHT, pushing hard: leaning forward with both arms stretched straight ahead at shoulder height and both open palms pressed flat against something invisible in front, eyes squeezed shut, gritted teeth." + tail()),
 'soldierC': ("3:2", ROW3 + f"LEFT copy: three-quarter view facing to the RIGHT, scraping: both hands gripping {SCRAPER}, the pole held out level at chest height pointing to the RIGHT with the blade end far from the body, leaning forward, a tired determined face with the tongue poking out of the corner of the mouth. MIDDLE copy: facing the viewer, giving up: a big shrug, both palms turned up at shoulder height, shoulders raised, eyebrows tilted up, a flat resigned mouth. RIGHT copy: three-quarter view facing to the LEFT, walking away sadly: mid-step, one hand carrying {CASE} at the side, shoulders slumped, head down, eyes half closed, a sad downturned mouth." + tail()),
 'objects': ("3:2", "Two separate objects side by side in one row with a wide empty gap between them, drawn at the same scale. LEFT: a chunky little industrial power machine: a squat fat round steel tank (#B9C2CB with a darker #8E99A4 shade) standing on four short stubby legs, a rounded dome lid on top, two thick bent grey pipes coming out of its two sides and curving down, one big round porthole window on its front face glowing warm yellow (#FFE45C), a small control box with three round buttons (red, yellow, green) on its right side, a row of round rivets around the middle. RIGHT: a slim tall white rocket standing upright on its tail: a long smooth white body (#F4F4F2 with a pale grey #D9DCE0 shade), a pointed red nose cone (#E8382E), four small red fins at the bottom, two thin black stripes around the middle. No faces, no flags. " + OBJ + " " + KEY('magenta')),
 'plane': ("3:2", "Side view of one chunky cartoon business jet airplane flying level toward the RIGHT: a long slim white fuselage (#F4F4F2 with a pale grey #D9DCE0 shade) with a rounded pointed nose on the RIGHT, a dark cockpit windshield near the nose, a row of five small round passenger windows, one long thin blue stripe (#2B5BB0) along the whole fuselage, swept-back wings, two small engines mounted at the back beside the tail, a tall T-shaped tail fin on the LEFT, and a long flat grey box-shaped radar pod mounted under the belly. Friendly simple shapes. No text, no letters, no numbers, no logos, no flags, no people, no clouds. The whole plane in frame with a margin. " + OBJ + " " + KEY()),
 'plate': ("2:3", "A school-diagram side cutaway of a thick arctic ice sheet, vertical picture. The top 30 % is a pale cold arctic sky (flat #D3EAF7) with one low pale-yellow sun (#FFF1B8) near the horizon on the LEFT and two small flat white clouds. At 30 % of the height lies the snow surface: a gently wavy bright white snow line (#FFFFFF) with a thick black outline and a few low rounded snow drifts. Below the surface everything is the inside of the ice sheet cut open like a slice of cake: three wide flat horizontal bands of ice, pale icy blue (#CDEBF7) at the top, a middle band of #A9D8EE and a deeper blue band (#86BFDF) at the bottom, separated by thin soft wavy lighter lines, with a few tiny white air-bubble dots. No tunnels, no buildings, no people, no animals, no text. " + BG),
}
json.dump(P, open('prompts.json', 'w'), indent=1)
with open('prompts.md', 'w') as f:
    f.write('# camp-century - picture prompts (all gpt-image-2.5-sunburst, 1K, quality LOW, 1 variation, no references)\n\n')
    for k, (ar, p) in P.items(): f.write(f'## {k} ({ar})\n{p}\n\n')
for k, (ar, p) in P.items(): print(k, ar, len(p))
